def solve(a, b):
    """
    Computes (a[i] * b[i] + 1) for each i in range(len(a)).
    Returns a list of integers.
    """
    if len(a) != len(b):
        raise ValueError("Input lists must be of equal length")
    if not a:
        return []
    return [x * y + 1 for x, y in zip(a, b)]

def solve(strings):
    if not strings:
        return 0
    if len(strings) == 1:
        return len(strings[0])

    # Find the shortest string to limit comparison scope
    min_len = min(len(s) for s in strings)

    # Compare characters at each position across all strings
    for i in range(min_len):
        char = strings[0][i]
        for s in strings[1:]:
            if s[i] != char:
                return i
    return min_len

