    def rand_str(max_len=10):
        length = rng.randint(1, max_len)
        chars = string.ascii_lowercase + string.digits
        return ''.join(rng.choice(chars) for _ in range(length))

    # Decide number of strings
    n_strings = rng.randint(0, 5)

    if n_strings == 0:
        return {"strings": []}

