        return {"strings": [rand_str(10)]}

    # Create strings with a guaranteed common prefix or not
    common_prefix = rand_str(rng.randint(0, 5))
    suffixes = []

    for _ in range(n_strings):
        suffix_len = rng.randint(0, 5)
        suffix = ''.join(rng.choice(string.ascii_lowercase + string.digits) for _ in range(suffix_len))
        suffixes.append(common_prefix + suffix)

    # Occasionally break the prefix for variety if it was non-empty
    if common_prefix and rng.random() < 0.3:
        # Modify one string to break the prefix at a random position
        idx = rng.randint(0, len(common_prefix) - 1)
        original_char = common_prefix[idx]
        new_char = rng.choice([c for c in string.ascii_lowercase + string.digits if c != original_char])
        modified = common_prefix[:idx] + new_char + common_prefix[idx+1:] + suffixes[rng.randint(0, n_strings-1)][len(common_prefix):]
        suffixes[rng.randint(0, n_strings-1)] = modified

    return {"strings": suffixes}

